  "content": "1|import type { NativeToolDefinition } from '../../../../../core/ai/tools/ToolRegistry';
2|import type { AiWebSearchSettings } from '../../../../../shared/api/contracts/ai/types';
3|import { createSsrfGuardedFetch, validateMcpRemoteUrl } from '../mcpUrlGuard';
4|import { formatFetchedBody, resolveFetchUrlFormat } from './htmlToReadableMarkdown';
5|import { executeScreenshotUrl, SCREENSHOT_URL_TOOL_NAME } from './webScreenshot';
6|
7|export const WEB_SEARCH_TOOL_NAME = 'web_search';
8|export const FETCH_URL_TOOL_NAME = 'fetch_url';
9|export { SCREENSHOT_URL_TOOL_NAME };
10|
11|export const FETCH_URL_TIMEOUT_MS = 30_000;
12|export const FETCH_URL_MAX_BYTES = 256_000;
13|
14|export type WebSearchType = 'web' | 'news' | 'images';
15|
16|export type WebSearchResult = {
17|  title: string;
18|  url: string;
19|  snippet: string;
20|};
21|
22|export type WebToolsDeps = {
23|  getWebSearchSettings: () => AiWebSearchSettings;
24|  fetchImpl?: typeof fetch;
25|  validateUrl?: typeof validateMcpRemoteUrl;
26|  screenshotImpl?: typeof executeScreenshotUrl;
27|};
28|
29|const WEB_SEARCH_TYPES: readonly WebSearchType[] = ['web', 'news', 'images'];
30|
31|const resolveSearchType = (raw: unknown): WebSearchType => {
32|  if (typeof raw === 'string' && (WEB_SEARCH_TYPES as readonly string[]).includes(raw.trim().toLowerCase())) {
33|    return raw.trim().toLowerCase() as WebSearchType;
34|  }
35|  return 'web';
36|};
37|
38|const truncateBody = (body: string): { text: string; truncated: boolean } => {
39|  if (Buffer.byteLength(body, 'utf8') <= FETCH_URL_MAX_BYTES) {
40|    return { text: body, truncated: false };
41|  }
42|
43|  let truncated = body;
44|  while (truncated.length > 0 && Buffer.byteLength(truncated, 'utf8') > FETCH_URL_MAX_BYTES) {
45|    truncated = truncated.slice(0, Math.floor(truncated.length * 0.9));
46|  }
47|
48|  return { text: `${truncated}\n… [content truncated]`, truncated: true };
49|};
50|
51|const resolveMaxResults = (
52|  args: Record<string, unknown>,
53|  settings: AiWebSearchSettings,
54|): number => {
55|  const fromArgs = typeof args.maxResults === 'number' && args.maxResults > 0
56|    ? Math.floor(args.maxResults)
57|    : undefined;
58|  const configured = settings.maxResults ?? 5;
59|  return Math.min(fromArgs ?? configured, 20);
60|};
61|
62|const mapSearchRecord = (record: Record<string, unknown>, urlKeys: string[], snippetKeys: string[]): WebSearchResult | null => {
63|  const title = typeof record.title === 'string' ? record.title.trim() : '';
64|  const url = urlKeys
65|    .map((key) => (typeof record[key] === 'string' ? String(record[key]).trim() : ''))
66|    .find((value) => value.length > 0) ?? '';
67|  const snippet = snippetKeys
68|    .map((key) => (typeof record[key] === 'string' ? String(record[key]).trim() : ''))
69|    .find((value) => value.length > 0) ?? '';
70|  if (!title || !url) return null;
71|  return { title, url, snippet };
72|};
73|
74|const parseResultList = (items: unknown, urlKeys: string[], snippetKeys: string[]): WebSearchResult[] => {
75|  if (!Array.isArray(items)) return [];
76|  return items
77|    .map((item) => {
78|      if (!item || typeof item !== 'object') return null;
79|      const record = item as Record<string, unknown>;
80|      const nestedUrl = record.properties && typeof record.properties === 'object'
81|        ? (record.properties as Record<string, unknown>).url
82|        : undefined;
83|      return mapSearchRecord(
84|        { ...record, ...(typeof nestedUrl === 'string' ? { nestedUrl } : {}) },
85|        [...urlKeys, 'nestedUrl'],
86|        snippetKeys,
87|      );
88|    })
89|    .filter((item): item is WebSearchResult => item !== null);
90|};
91|
92|const parseBraveResults = (payload: unknown, type: WebSearchType): WebSearchResult[] => {
93|  if (!payload || typeof payload !== 'object') return [];
94|  const record = payload as { web?: { results?: unknown[] }; results?: unknown[] };
95|  if (type === 'web') return parseResultList(record.web?.results, ['url'], ['description']);
96|  return parseResultList(record.results, ['url'], ['description']);
97|};
98|
99|const parseTavilyResults = (payload: unknown): WebSearchResult[] => {
100|  if (!payload || typeof payload !== 'object') return [];
101|  return parseResultList((payload as { results?: unknown[] }).results, ['url'], ['content']);
102|};
103|
104|const parseSerperResults = (payload: unknown, type: WebSearchType): WebSearchResult[] => {
105|  if (!payload || typeof payload !== 'object') return [];
106|  const record = payload as { organic?: unknown[]; news?: unknown[]; images?: unknown[] };
107|  if (type === 'news') return parseResultList(record.news, ['link'], ['snippet']);
108|  if (type === 'images') return parseResultList(record.images, ['imageUrl', 'link'], ['title']);
109|  return parseResultList(record.organic, ['link'], ['snippet']);
110|};
