112|export const executeWebSearch = async (
113|  args: Record<string, unknown>,
114|  deps: WebToolsDeps,
115|): Promise<{ ok: true; summary: string; data: { type: WebSearchType; results: WebSearchResult[] } } | { ok: false; summary: string; error: string }> => {
116|  const query = typeof args.query === 'string' ? args.query.trim() : '';
117|  if (!query) {
118|    return { ok: false, summary: 'Search query is required.', error: 'missing_query' };
119|  }
120|  if (query.length > 500) {
121|    return { ok: false, summary: 'Search query is too long (max 500 characters).', error: 'query_too_long' };
122|  }
123|
124|  const settings = deps.getWebSearchSettings();
125|  if (settings.provider === 'disabled') {
126|    return {
127|      ok: false,
128|      summary: 'Web search is disabled. Configure a provider in Settings → MCP Servers.',
129|      error: 'web_search_disabled',
130|    };
131|  }
132|
133|  const apiKey = settings.apiKey?.trim();
134|  if (!apiKey) {
135|    return {
136|      ok: false,
137|      summary: 'Web search API key is not configured.',
138|      error: 'missing_api_key',
139|    };
140|  }
141|
142|  const searchType = resolveSearchType(args.type);
143|  if (settings.provider === 'tavily' && searchType === 'images') {
144|    return {
145|      ok: false,
146|      summary: 'Tavily does not support image search. Use type "web" or "news", or switch provider.',
147|      error: 'type_not_supported',
148|    };
149|  }
150|
151|  const maxResults = resolveMaxResults(args, settings);
152|  const fetchImpl = deps.fetchImpl ?? fetch;
153|
154|  try {
155|    let results: WebSearchResult[] = [];
156|
157|    if (settings.provider === 'brave') {
158|      const path = searchType === 'news'
159|        ? 'https://api.search.brave.com/res/v1/news/search'
160|        : searchType === 'images'
161|          ? 'https://api.search.brave.com/res/v1/images/search'
162|          : 'https://api.search.brave.com/res/v1/web/search';
163|      const url = new URL(path);
164|      url.searchParams.set('q', query);
165|      url.searchParams.set('count', String(maxResults));
166|
167|      const response = await fetchImpl(url.toString(), {
168|        method: 'GET',
169|        headers: {
170|          Accept: 'application/json',
171|          'X-Subscription-Token': apiKey,
172|        },
173|        signal: AbortSignal.timeout(FETCH_URL_TIMEOUT_MS),
174|      });
175|
176|      if (!response.ok) {
177|        return {
178|          ok: false,
179|          summary: `Brave search failed (HTTP ${response.status}).`,
180|          error: 'provider_error',
181|        };
182|      }
183|
184|      results = parseBraveResults(await response.json(), searchType);
185|    } else if (settings.provider === 'tavily') {
186|      const response = await fetchImpl('https://api.tavily.com/search', {
187|        method: 'POST',
188|        headers: {
189|          Accept: 'application/json',
190|          'Content-Type': 'application/json',
191|        },
192|        body: JSON.stringify({
193|          api_key: apiKey,
194|          query,
195|          max_results: maxResults,
196|          topic: searchType === 'news' ? 'news' : 'general',
197|        }),
198|        signal: AbortSignal.timeout(FETCH_URL_TIMEOUT_MS),
199|      });
200|
201|      if (!response.ok) {
202|        return {
203|          ok: false,
204|          summary: `Tavily search failed (HTTP ${response.status}).`,
205|          error: 'provider_error',
206|        };
207|      }
208|
209|      results = parseTavilyResults(await response.json());
210|    } else if (settings.provider === 'serper') {
211|      const endpoint = searchType === 'news'
212|        ? 'https://google.serper.dev/news'
213|        : searchType === 'images'
214|          ? 'https://google.serper.dev/images'
215|          : 'https://google.serper.dev/search';
216|      const response = await fetchImpl(endpoint, {
217|        method: 'POST',
218|        headers: {
219|          Accept: 'application/json',
220|          'Content-Type': 'application/json',
221|          'X-API-KEY': apiKey,
222|        },
223|        body: JSON.stringify({
224|          q: query,
225|          num: maxResults,
226|        }),
227|        signal: AbortSignal.timeout(FETCH_URL_TIMEOUT_MS),
228|      });
229|
230|      if (!response.ok) {
231|        return {
232|          ok: false,
233|          summary: `Serper search failed (HTTP ${response.status}).`,
234|          error: 'provider_error',
235|        };
236|      }
237|
238|      results = parseSerperResults(await response.json(), searchType);
239|    }
240|
241|    const limited = results.slice(0, maxResults);
242|    return {
243|      ok: true,
244|      summary: `Found ${limited.length} ${searchType} result(s) for "${query}".`,
245|      data: { type: searchType, results: limited },
246|    };
247|  } catch (error) {
248|    const message = error instanceof Error ? error.message : String(error);
249|    return {
250|      ok: false,
251|      summary: `Web search failed: ${message}`,
252|      error: 'provider_error',
253|    };
254|  }
255|};
